/**
 * 港鐵路綫圖（自己畫嘅簡化示意圖，唔係港鐵官方圖）：格仔座標，綫只行橫、直、45°；轉彎 45° 或者 90°，用圓弧（統一半徑，並排綫同心）。
 * 站嘅位置參考真實地理（OpenStreetMap 站點：市區放大、新界收細），海岸綫由 OSM 跟站位置變形出嚟，
 * 所以地圖要註明「© OpenStreetMap 貢獻者」。網頁（SVG）同 App（react-native-svg）共用。1 格大約 44px。
 *
 * - paths：每條綫一段或幾段折綫（包轉角位）；轉角點可以有第三個數 = 彎位半徑（並排綫一齊轉彎，外面嗰條加 G，同心貼住）
 * - stations：每條綫喺每個站嘅點；每點一個黑邊白圈（圈心喺綫正中），轉車站幾個圈重疊成「8」字（點可以橫、直或者打斜排）
 * - labels：站名喺站嘅邊個方向（n s e w ne nw se sw），唔寫就 s
 */
export type Pt = readonly [number, number];
/** 折綫點：可以帶彎位半徑（冇就用 MTR_MAP_RADIUS） */
export type PathPt = readonly [number, number] | readonly [number, number, number];
export type LabelSide = 'n' | 's' | 'e' | 'w' | 'ne' | 'nw' | 'se' | 'sw';

export interface MtrMapLine {
  line: string;
  paths: readonly (readonly PathPt[])[];
  stations: Readonly<Record<string, Pt>>;
}

export const MTR_MAP_VIEW = { minX: -2.8, minY: -2.6, width: 36.2, height: 29.8 } as const;

