/** 站名位置（冇寫就喺下面） */
export const MTR_MAP_LABELS: Readonly<Record<string, LabelSide>> = {
  CEN: 's', ADM: 'sw', SKW: 'e', HFC: 'e', CHW: 'e', TST: 'w', JOR: 'w', YMT: 'w', MOK: 'w', PRE: 'w', SSP: 's', CSW: 'n', LCK: 's', MEF: 'ne', LAK: 'n', KWF: 'e', KWH: 'e', TWH: 'e', TSW: 'n', WHA: 'e', HOM: 'ne', SKM: 'e', KOT: 'nw', LOF: 'n', WTS: 'n', DIH: 'se', CHH: 'n', KOB: 'e', NTK: 'e', KWT: 'e', LAT: 'e', YAT: 'n', TIK: 'n', NOP: 's', QUB: 's', TKO: 's', HAH: 'e', POA: 'e', LHP: 'e', TUM: 's', SIH: 'w', TIS: 'n', LOP: 's', YUL: 's', KSR: 'n', TWW: 'sw', NAC: 'e', AUS: 'ne', ETS: 'n', HUH: 'se', TKW: 'se', SUW: 'e', KAT: 'e', HIK: 'n', TAW: 'w', CKT: 's', STW: 'n', CIO: 's', SHM: 'n', TSH: 'se', HEO: 'se', MOS: 'n', WKS: 'n', EXC: 'n', MKK: 'e', SHT: 'nw', FOT: 'nw', UNI: 'nw', TAP: 'ne', TWO: 'ne', FAN: 's', SHS: 's', LOW: 'n', LMC: 'w', OCP: 'e', WCH: 's', LET: 's', SOH: 's', HOK: 'nw', KOW: 'w', OLY: 'w', TSY: 'se', SUN: 'se', TUC: 'w', AIR: 'n', AWE: 'n', DIS: 's',
};

/** 站名同站粒之間額外留位（例如奧運：左邊仲有機場快綫） */
export const MTR_MAP_LABEL_GAP: Readonly<Record<string, number>> = { OLY: 0.42 };

/**
 * 站圈（外半徑）：黑邊白圈，圈心喺條綫正中，直徑大約綫闊兩倍。轉車站每條綫一個圈，並排綫相隔 MTR_MAP_GAP，
 * 幾個圈重疊成「8」字（先畫晒黑圈再畫白心，中間唔見黑邊），每個圈入面一條綫色短棒（沿住「8」字方向）。
 */
export const MTR_MAP_DOT_R = 0.17;
/** 站圈黑邊厚度 */
export const MTR_MAP_RING = 0.04;
/** 轉車站圈入面綫色短棒：長度、闊度 */
export const MTR_MAP_TICK = { len: 0.12, width: 0.04 } as const;

export interface MtrMapStation {
  code: string;
  /** 各綫嘅點（同 lines 一一對應；分岔站係兩點、一條綫） */
  pts: Pt[];
  lines: string[];
  /** 所有站圈嘅範圍（站名同撳嘅範圍用） */
  box: { x: number; y: number; w: number; h: number };
  label: LabelSide;
  /** 站名額外留位 */
  labelGap: number;
}

const dist = (a: readonly number[], b: readonly number[]) => Math.hypot(a[0]! - b[0]!, a[1]! - b[1]!);

/** 由綫嘅資料整理出每個站（各綫嘅點、圈嘅範圍、經過嘅綫） */
export function mtrMapStations(): MtrMapStation[] {
  const map = new Map<string, { pts: Pt[]; lines: string[] }>();
  for (const l of MTR_MAP_LINES) {
    for (const [code, p] of Object.entries(l.stations)) {
      const s = map.get(code) ?? { pts: [], lines: [] };
      if (MTR_MAP_DOUBLE.includes(code)) {
        // 分岔站：喺條綫兩邊各半個 G 一個圈
        const seg = l.paths.flatMap((path) => path.slice(1).map((b, i) => [path[i]!, b] as const)).find(([a, b]) => dist(a, b) > 0 && onSeg(p, a, b))!;
        const len = dist(seg[0], seg[1]);
        const nx = -(seg[1][1] - seg[0][1]) / len;
        const ny = (seg[1][0] - seg[0][0]) / len;
        const h = MTR_MAP_GAP / 2;
        s.pts.push([+(p[0] - nx * h).toFixed(4), +(p[1] - ny * h).toFixed(4)], [+(p[0] + nx * h).toFixed(4), +(p[1] + ny * h).toFixed(4)]);
      } else s.pts.push(p);
      if (!s.lines.includes(l.line)) s.lines.push(l.line);
      map.set(code, s);
    }
  }
  return [...map.entries()].map(([code, s]) => {
    const r = MTR_MAP_DOT_R;
    const xs = s.pts.map((p) => p[0]);
    const ys = s.pts.map((p) => p[1]);
    const x0 = Math.min(...xs) - r;
    const y0 = Math.min(...ys) - r;
    const box = { x: x0, y: y0, w: Math.max(...xs) + r - x0, h: Math.max(...ys) + r - y0 };
    return { code, pts: s.pts, lines: s.lines, box, label: MTR_MAP_LABELS[code] ?? 's', labelGap: MTR_MAP_LABEL_GAP[code] ?? 0 };
  });
}

/** 站名擺位：相對站粒範圍，回傳文字錨點（x、y）同對齊（start／middle／end） */
export function mtrLabelPos(box: MtrMapStation['box'], side: LabelSide, gap = 0.14): { x: number; y: number; anchor: 'start' | 'middle' | 'end'; baseline: 'top' | 'middle' | 'bottom' } {
  const cx = box.x + box.w / 2;
  const cy = box.y + box.h / 2;
  const right = box.x + box.w + gap;
  const left = box.x - gap;
  const top = box.y - gap;
  const bottom = box.y + box.h + gap;
  switch (side) {
    case 'n':
      return { x: cx, y: top, anchor: 'middle', baseline: 'bottom' };
    case 's':
      return { x: cx, y: bottom, anchor: 'middle', baseline: 'top' };
    case 'e':
      return { x: right, y: cy, anchor: 'start', baseline: 'middle' };
    case 'w':
      return { x: left, y: cy, anchor: 'end', baseline: 'middle' };
    case 'ne':
      return { x: right, y: top, anchor: 'start', baseline: 'bottom' };
    case 'nw':
      return { x: left, y: top, anchor: 'end', baseline: 'bottom' };
    case 'se':
      return { x: right, y: bottom, anchor: 'start', baseline: 'top' };
    case 'sw':
      return { x: left, y: bottom, anchor: 'end', baseline: 'top' };
  }
}

/** 點 p 喺唔喺線段 a–b 上（容差 0.01） */
function onSeg(p: readonly number[], a: readonly number[], b: readonly number[]) {
  return Math.abs(dist(a, p) + dist(p, b) - dist(a, b)) < 0.01;
}

/** 折綫 → SVG path「M x y L x y …」（直角） */
export function mtrPathD(pts: readonly PathPt[]): string {
  return pts.map((p, i) => `${i ? 'L' : 'M'}${p[0]} ${p[1]}`).join(' ');
}


/**
 * 港鐵綫 → SVG path：每個轉角（45° 或 90°）一段圓弧，半徑用點嘅第三個數（冇就 MTR_MAP_RADIUS）。
 * 並排綫座標已經寫好同心半徑，所以轉彎都貼住。段唔夠長就縮細（安全網，座標檢查過唔會發生）。
 */
export function mtrLinePathD(pts: readonly PathPt[]): string {
  if (pts.length < 3) return mtrPathD(pts);
  const f = (n: number) => +n.toFixed(4);
  let d = `M${pts[0]![0]} ${pts[0]![1]}`;
  // 每段已經用咗幾多（前一個彎位）
  let used = 0;
  for (let i = 1; i < pts.length - 1; i++) {
    const a = pts[i - 1]!;
    const p = pts[i]!;
    const b = pts[i + 1]!;
    const la = dist(a, p);
    const lb = dist(p, b);
    const ua = [(a[0] - p[0]) / la, (a[1] - p[1]) / la];
    const ub = [(b[0] - p[0]) / lb, (b[1] - p[1]) / lb];
    // 轉咗幾多度：入嚟方向同出去方向夾角
    const theta = Math.acos(Math.max(-1, Math.min(1, -(ua[0]! * ub[0]! + ua[1]! * ub[1]!))));
    if (theta < 1e-3) {
      used = 0;
      continue;
    }
    let r = p[2] ?? MTR_MAP_RADIUS;
    let t = r * Math.tan(theta / 2);
    const tMax = Math.min(la - used, lb / 2);
    if (t > tMax) {
      t = Math.max(0, tMax);
      r = t / Math.tan(theta / 2);
    }
    used = t;
    const p1 = [p[0] + ua[0]! * t, p[1] + ua[1]! * t];
    const p2 = [p[0] + ub[0]! * t, p[1] + ub[1]! * t];
    // 順時針（SVG y 向下：叉積 > 0）→ sweep 1
    const cross = (p[0] - a[0]) * (b[1] - p[1]) - (p[1] - a[1]) * (b[0] - p[0]);
    d += ` L${f(p1[0]!)} ${f(p1[1]!)} A${f(r)} ${f(r)} 0 0 ${cross > 0 ? 1 : 0} ${f(p2[0]!)} ${f(p2[1]!)}`;
  }
  const last = pts[pts.length - 1]!;
  return `${d} L${last[0]} ${last[1]}`;
}

/**
 * 折綫 → 圓角 SVG path（二次曲綫，由轉角起計 radius 格開始彎）：海岸綫用（任何角度都得）。
 * stations：呢啲點附近唔好彎（安全網）。
 */
export function mtrRoundPathD(pts: readonly Pt[], stations: readonly Pt[] = [], radius = 0.3): string {
  if (pts.length < 3) return mtrPathD(pts);
  let d = `M${pts[0]![0]} ${pts[0]![1]}`;
  for (let i = 1; i < pts.length - 1; i++) {
    const a = pts[i - 1]!;
    const p = pts[i]!;
    const b = pts[i + 1]!;
    let r = Math.min(radius, dist(a, p) / 2, dist(p, b) / 2);
    for (const s of stations) if (onSeg(s, a, p) || onSeg(s, p, b)) r = Math.min(r, dist(s, p) - 0.3);
    if (r <= 0.05) {
      d += ` L${p[0]} ${p[1]}`;
      continue;
    }
    const ka = r / dist(a, p);
    const kb = r / dist(p, b);
    const p1: Pt = [p[0] + (a[0] - p[0]) * ka, p[1] + (a[1] - p[1]) * ka];
    const p2: Pt = [p[0] + (b[0] - p[0]) * kb, p[1] + (b[1] - p[1]) * kb];
    d += ` L${+p1[0].toFixed(3)} ${+p1[1].toFixed(3)} Q${p[0]} ${p[1]} ${+p2[0].toFixed(3)} ${+p2[1].toFixed(3)}`;
  }
  const last = pts[pts.length - 1]!;
  return `${d} L${last[0]} ${last[1]}`;
}
